decisions:
    if (!pageable(e)) return error.NoPagedCaches;
    const sharded = e.settings.kv_shard.on; // port note (af9777b49): the fork's TF_GLM_KV_SHARD beside upstream's TF_GLM_KV_HOST
    const fixed = try state.State.pagedBytesFor(gpa, &e.w, e.capacity, tableLen(e.capacity), e.mtp, sharded);
    const page = if (kv_host.onHost() and !sharded) state.pkPageBytes(&e.w) else pageBytes(e);
    const token = if (sharded) geometry(e).tokenBytes() else page / state.page_rows;
    return .{ .fixed_bytes = fixed + extra, .token_bytes = token, .page_tokens = state.page_rows, .snap_bytes = 0 };
}

/// TF_KV_SHARE: a kept state's slot (`e.share_pages`: its prefix's pages left to the store), at the window's last mark.
pub fn shareSlot(e: *const Engine) u64 {
    return e.stateBytes(e.capacity - e.capacity % @import("cuda_native.zig").snap_grid);
}

/// The sharded page's parts for engine `e`: its DSA layers' latent rows and pooled keys (the MTP head is refused).
pub fn geometry(e: *const Engine) kvs.Geometry {
    return kvs.Geometry.of(&e.w.config, state.mlaLayers(&e.w));
}

/// A page's bytes for engine `e`: its cache format's parts, the target MTP head's only when it is loaded.
pub fn pageBytes(e: *const Engine) u64 {
    return state.pageBytesOf(&e.w, e.settings.kv8, e.mtp);
}

/// Whether engine `e` has caches to page: a thin model of KDA layers alone (TF_GLM_LAYERS) without the target MTP head
/// has none, so its sequences keep their windows (of no KV rows) whatever TF_KV_PAGES says.
pub fn pageable(e: *const Engine) bool {
    return pageBytes(e) > 0;
}

/// A paged sequence of engine `e`'s format on the pages at `at`.
fn pagedState(e: *const Engine, at: state.Paged) !fw.State {
    return fw.State.initPagedFormat(e.gpa, e.d, &e.w, e.capacity, at, e.settings.kv8, e.mtp);

const sharded = e.settings.kv_shard.on; // port note (af9777b49): the fork's shard beside upstream's host pages
const page = if (kv_host.onHost() and !sharded) state.pkPageBytes(&e.w) else l.pageBytes();
p.* = .{ .gpa = gpa, .e = e, .layout = l, .page = page, .pool = try kv.Pool.init(gpa, if (sharded) 0 else pages, page), .arena = null, .leases = &.{}, .used = &.{}, .leader = leader, .poison = poisoned() };
errdefer p.pool.deinit();
const host = kv_host.onHost() and pages > 0 and !sharded;
if (pages > 0 and !host and !sharded) p.arena = try cuda.DeviceBuffer.alloc(e.d, pages * page);
errdefer if (p.arena) |*a| a.free();
if (sharded) p.shard = try initShard(gpa, e, streams, pages, leader); // port note (af9777b49)
errdefer if (p.shard) |x| freeShard(gpa, x);
if (host) {
    if (kv_host.shared()) {
        p.shared = try kv_host.SharedPages.open(e.d, pages * page, leader, e.share.world);
        p.host_ptr = p.shared.?.dev;
    } else {
        p.host = try cuda.HostBuffer.allocMapped(e.d, pages * page);
        p.host_ptr = try p.host.?.device();
    }
    p.pk_arena = try cuda.DeviceBuffer.alloc(e.d, pages * state.pkPageBytes(&e.w));
    try kv_host.prepare(e.d, page, e.capacity, e.w.config.kv_lora * 2); // made before the room was read
    std.log.info("kv host: {d} pages ({d} MiB) in pinned host memory, pooled keys {d} MiB on the device", .{ pages, pages * page >> 20, pages * state.pkPageBytes(&e.w) >> 20 });
}
errdefer if (p.host) |*h| h.free();
errdefer if (p.shared) |*h| h.close();
errdefer if (p.pk_arena) |*a| a.free();

if (p.shard) |x| return onShard(e, x.keys.?.ptr, x.lat.?.ptr); // port note (af9777b49): the shard's own tables
var at = on(e, p.base(), page);
if (p.pk_arena) |a| {
    at.pk = a.ptr;
    at.pk_page = state.pkPageBytes(&e.w);
}

    return p.openWith(slot, prompt, max_tokens, null, &.{});
}

/// The shared store's pages a resume held, given back when no lease took them.

/// `open`, sharded in `home` (a kept state's part) when it has the room (cuda_kv_shard.Parts.choose), with a twin
/// of the prompt's pages in the other part under TF_GLM_KV_SHARD_TWINS when it has them. The ids that cross with
/// the begin step: the stream's, then its twin's (`twinCount`). With `adopted` (the shared store's pages a resume
/// held, first in the lease): the stream opens in their part and there it stays — no fall-back to the other part
/// (LaneMemory: the request waits, as a kept state's home does when carries are off), and no twin (its adopted
/// prefix's latent rows exist on the owner alone; the pass runs owner-computed, cuda_kv_shard_attn).
pub fn openWith(p: *Pages, slot: u32, prompt: usize, max_tokens: usize, home: ?u8, adopted: []const u32) ![]const u32 {
    var held = adopted.len > 0;
    errdefer if (held) for (adopted) |id| p.pool.release(id);

for (ids) |id| if (id >= p.pool.total()) return error.BadStep; // port note (af9777b49): the fork's bounds check
const st = &p.e.seqs.items[slot].?.st;
const page = p.page;
if (p.poison) for (ids[kept..]) |id| try p.e.d.check(p.e.d.api.cuMemsetD32Async(p.base() + id * page, 0xFFFF_FFFF, page / 4, p.e.stream.handle), "cuMemsetD32Async");

if (p.shard) |x| { // port note (af9777b49): the shard's slot closes its own tables
    st.lpages = &.{};
    st.hold = null;
    x.parts.close(slot);
    x.lids[slot].clearRetainingCapacity();
    return;
}
if (kv_host.active) |*g| g.invalidate(p.e.stream) catch {};
